    'Major markets are closed for the weekend — global trading reopens Sunday at 6:00 PM ET (Shanghai opens Monday 9:00 AM Beijing / 8:00 PM ET).': ['ตลาดหลักปิดช่วงสุดสัปดาห์ — ตลาดโลกเปิดอีกครั้งคืนวันอาทิตย์ 18:00 น. ET (เซี่ยงไฮ้เปิดวันจันทร์ 09:00 น. เวลาปักกิ่ง)', 'ຕະຫຼາດຫຼັກປິດທ້າຍອາທິດ — ຕະຫຼາດໂລກເປີດອີກຄັ້ງວັນອາທິດ 18:00 ET (ຊຽງໄຮ້ເປີດວັນຈັນ 09:00 ເວລາປັກກິ່ງ)', 'Los mercados principales están cerrados por el fin de semana — reabren el domingo a las 6:00 PM ET (Shanghái abre lunes 9:00 AM hora de Pekín).', '主要市场周末休市 — 全球交易将于美东周日18:00重开（上海周一北京时间09:00开盘）。', '主要市場は週末休場中です — 世界市場は米国東部日曜18:00に再開します（上海は月曜北京時間09:00開始）。', 'प्रमुख बाज़ार सप्ताहांत के लिए बंद हैं — वैश्विक व्यापार रविवार शाम 6:00 बजे ET पर फिर खुलेगा (शंघाई सोमवार सुबह 9:00 बजे बीजिंग समय)।'],
    'Daily 5:00–6:00 PM ET market break: trading is very light, so prices can briefly jump or dip more easily.': ['ช่วงพักตลาดประจำวัน 17:00–18:00 น. ET: ปริมาณซื้อขายเบาบาง ราคาอาจกระโดดหรือย่อสั้นๆ ได้ง่าย', 'ຊ່ວງພັກຕະຫຼາດປະຈຳວັນ 17:00–18:00 ET: ການຊື້ຂາຍເບົາບາງ ລາຄາອາດຂຶ້ນລົງໄວໄດ້ງ່າຍ', 'Pausa diaria de 5:00 a 6:00 PM ET: el volumen es muy bajo y el precio puede moverse con facilidad.', '每日美东17:00–18:00休市维护：交投清淡，价格容易短暂波动。', '米国東部17:00〜18:00の日次休止時間：取引が薄いため価格が一時的に動きやすくなります。', 'दैनिक 5:00–6:00 PM ET बाज़ार ब्रेक: व्यापार बहुत हल्का होता है, इसलिए कीमतें अचानक हिल सकती हैं।'],
    'Both London and New York are open right now — busiest trading hours and most reliable pricing of the day.': ['ทั้งลอนดอนและนิวยอร์กเปิดพร้อมกันตอนนี้ — ช่วงเวลาคึกคักที่สุดและราคาชัดเจนที่สุดของวัน', 'ທັງລອນດອນ ແລະ ນິວຢອກເປີດພ້ອມກັນຕອນນີ້ — ຊ່ວງເວລາຄຶກຄັກທີ່ສຸດຂອງມື້', 'Londres y Nueva York están abiertos a la vez — las horas más activas y confiables del día.', '伦敦与纽约市场同时开放 — 全天交易最活跃、定价最可靠的时段。', 'ロンドンとニューヨークが同時に開場中 — 1日で最も取引が活発で信頼性の高い時間帯です。', 'लंदन और न्यूयॉर्क दोनों अभी खुले हैं — दिन का सबसे व्यस्त और भरोसेमंद ट्रेडिंग समय।'],
    'Asia & Shanghai physical buyers are leading the market right now while US and European main desks sleep.': ['ผู้ซื้อทองจริงในเอเชียและเซี่ยงไฮ้กำลังนำตลาดอยู่ในขณะที่ตลาดสหรัฐฯ และยุโรปพักอยู่', 'ຜູ້ຊື້ຄຳຈິງໃນເອເຊຍ ແລະ ຊຽງໄຮ້ກຳລັງນຳຕະຫຼາດຢູ່ໃນຂະນະທີ່ສະຫະລັດ ແລະ ເອີຣົບພັກຢູ່', 'Los compradores físicos de Asia y Shanghái lideran el mercado mientras EE. UU. y Europa duermen.', '亚洲与上海实物买家正在主导行情，欧美主盘目前休市。', '欧米の主要市場が休場中のため、アジア・上海の実物買いが相場を主導しています。', 'अभी एशिया और शंघाई के भौतिक खरीदार बाज़ार चला रहे हैं जबकि अमेरिका और यूरोप बंद हैं।'],
    'Global bullion trading is active right now — glowing green hubs show which exchanges are live.': ['ตลาดทองคำโลกกำลังซื้อขายอยู่ตอนนี้ — จุดสีเขียวแสดงตลาดที่เปิดอยู่', 'ຕະຫຼາດຄຳໂລກກຳລັງຊື້ຂາຍຢູ່ຕອນນີ້ — ຈຸດສີຂຽວສະແດງຕະຫຼາດທີ່ເປີດຢູ່', 'El comercio mundial de metales está activo ahora — los puntos verdes muestran los mercados abiertos.', '全球贵金属交易进行中 — 绿色发光节点表示正在开盘的交易所。', '世界の地金市場が取引中です — 緑色に光る拠点が開場中の市場です。', 'वैश्विक बुलियन ट्रेडिंग अभी सक्रिय है — चमकते हरे बिंदु खुले बाज़ार दिखाते हैं।'],

