    'Official Shanghai daily reference prices load automatically.': ['โหลดราคาอ้างอิงรายวันอย่างเป็นทางการของเซี่ยงไฮ้อัตโนมัติ', 'ໂຫຼດລາຄາອ້າງອີງລາຍວັນຂອງຊຽງໄຮ້ໂດຍອັດຕະໂນມັດ', 'Los precios oficiales diarios de Shanghái se cargan automáticamente.', '自动加载上海黄金交易所每日官方参考价。', '上海の公式日次基準価格を自動で読み込みます。', 'शंघाई की आधिकारिक दैनिक संदर्भ कीमतें स्वतः लोड होती हैं।'],
    'World Physical Gold Board': ['กระดานราคาทองคำจริงทั่วโลก', 'ກະດານລາຄາຄຳຈິງທົ່ວໂລກ', 'Tablero Mundial de Oro Físico', '全球实物黄金价格看板', '世界の実物ゴールド価格ボード', 'विश्व भौतिक सोना बोर्ड'],
    'Live local street-unit prices across 7 major physical gold markets (US, China, Thailand, Laos, India, Dubai & Japan)': ['ราคาทองคำตามหน่วยท้องถิ่นจริงใน 7 ตลาดใหญ่ (สหรัฐฯ จีน ไทย ลาว อินเดีย ดูไบ และญี่ปุ่น)', 'ລາຄາຄຳຕາມໜ່ວຍທ້ອງຖິ່ນຈິງໃນ 7 ຕະຫຼາດໃຫຍ່ (ສະຫະລັດ ຈີນ ໄທ ລາວ ອິນເດຍ ດູໄບ ແລະ ຍີ່ປຸ່ນ)', 'Precios locales en vivo en 7 grandes mercados físicos (EE. UU., China, Tailandia, Laos, India, Dubái y Japón)', '7大实物黄金市场本地计价单位实时看板（美国、中国、泰国、老挝、印度、迪拜、日本）', '主要7市場の現地単位ライブ価格（米国・中国・タイ・ラオス・インド・ドバイ・日本）', '7 प्रमुख बाज़ारों में स्थानीय इकाइयों के लाइव भाव (अमेरिका, चीन, थाईलैंड, लाओस, भारत, दुबई, जापान)'],
    'Pure Melt': ['เนื้อทองแท้', 'ເນື້ອຄຳແທ້', 'Valor Puro', '纯金折算', '地金純価', 'शुद्ध मूल्य'],
    'Est. Shop': ['ราคาหน้าร้าน', 'ລາຄາໜ້າຮ້ານ', 'Tienda Est.', '预计门店价', '店頭目安', 'अनुमानित दुकान'],
    'Thai & Lao Baht-weight uses the standard 15.244g bar at 96.5% purity · India 24K & 22K per 10g · Updated live with 21 world currencies.': ['น้ำหนัก 1 บาทไทยและลาวใช้มาตรฐานทองแท่ง 15.244 กรัม ความบริสุทธิ์ 96.5% · อินเดีย 24K และ 22K ต่อ 10 กรัม · อัปเดตสด 21 สกุลเงิน', 'ນ້ຳໜັກ 1 ບາດໄທ ແລະ ລາວໃຊ້ມາດຕະຖານ 15.244 ກຣາມ 96.5% · ອິນເດຍ 24K & 22K ຕໍ່ 10 ກຣາມ · ອັບເດດສົດ 21 ສະກຸນເງິນ', 'El peso Baht de Tailandia y Laos usa lingote estándar de 15.244g al 96.5% · India 24K y 22K por 10g · Actualizado en vivo con 21 monedas.', '泰铢与老挝铢重按标准96.5%纯度15.244克金条换算 · 印度24K与22K按每10克计价 · 随21种货币实时更新。', 'タイ・ラオスのバーツ重量は標準15.244g（純度96.5%）基準・インド24K/22Kは10g換算・21通貨でライブ更新。', 'थाई और लाओ बात-वज़न 96.5% शुद्धता के 15.244 ग्राम बार पर आधारित है · भारत 24K और 22K प्रति 10 ग्राम · 21 मुद्राओं के साथ लाइव अपडेट।'],

