    "Who's Buying: Asia vs. London vs. New York": ['ใครกำลังซื้อ: เอเชีย vs ลอนดอน vs นิวยอร์ก', 'ໃຜກຳລັງຊື້: ເອເຊຍ vs ລອນດອນ vs ນິວຢອກ', 'Quién Compra: Asia vs. Londres vs. Nueva York', '谁在买入：亚洲 vs 伦敦 vs 纽约', '買い手の地域比較：アジア vs ロンドン vs NY', 'कौन खरीद रहा है: एशिया बनाम लंदन बनाम न्यूयॉर्क'],
