    'No purchases saved yet. Add your coins or bars above to track your exact average cost and profit.': ['ยังไม่มีรายการซื้อ เพิ่มเหรียญหรือแท่งด้านบนเพื่อติดตามต้นทุนเฉลี่ยและกำไรที่แม่นยำ', 'ຍັງບໍ່ມີລາຍການຊື້ ເພີ່ມຫຼຽນ ຫຼື ແທ່ງດ້ານເທິງເພື່ອຕິດຕາມຕົ້ນທຶນ ແລະ ກຳໄລ', 'Aún no hay compras guardadas. Añade tus monedas o lingotes arriba para seguir tu costo y ganancia.', '尚未保存买入记录。在上方添加金币或金条即可追踪准确均价与盈亏。', '購入履歴がまだありません。上で追加すると平均取得単価と損益を自動追跡します。', 'अभी कोई खरीद सहेजी नहीं गई है। सटीक औसत लागत और लाभ के लिए ऊपर जोड़ें।'],
    'Gold vs. Silver Breakdown': ['สัดส่วนทองคำเทียบกับเงิน', 'ສັດສ່ວນຄຳທຽບກັບເງິນ', 'Desglose de Oro y Plata', '黄金与白银明细分布', '金・銀の内訳', 'सोना बनाम चांदी विवरण'],
    "Weight (oz / g / kg), share of stack, today's gain & China price value": ['น้ำหนัก (ออนซ์/กรัม/กก.) สัดส่วน กำไรวันนี้ และมูลค่าตามราคาจีน', 'ນ້ຳໜັກ (ອອນສ໌/ກຣາມ/ກກ.) ສັດສ່ວນ ກຳໄລມື້ນີ້ ແລະ ມູນຄ່າຕາມລາຄາຈີນ', 'Peso (oz/g/kg), proporción, ganancia de hoy y valor a precios de China', '重量（盎司/克/千克）、占比、今日涨跌及中国市场估值', '重量（oz/g/kg）・比率・本日損益・中国価格換算', 'वज़न (oz/g/kg), हिस्सा, आज का लाभ और चीन मूल्य'],
    'Enter your Gold or Silver ounces above to see your breakdown.': ['กรอกจำนวนออนซ์ทองคำหรือเงินด้านบนเพื่อดูรายละเอียด', 'ໃສ່ຈຳນວນອອນສ໌ຄຳ ຫຼື ເງິນດ້ານເທິງເພື່ອເບິ່ງລາຍລະອຽດ', 'Ingresa tus onzas de oro o plata arriba para ver el desglose.', '在上方输入黄金或白银盎司数即可查看详细分布。', '上に金・銀のオンス数を入力すると内訳が表示されます。', 'विवरण देखने के लिए ऊपर सोने या चांदी के औंस दर्ज करें।'],
    'Dollar Impact & What-If Values': ['ผลกระทบดอลลาร์และมูลค่าจำลอง', 'ຜົນກະທົບໂດລາ ແລະ ມູນຄ່າຈຳລອງ', 'Impacto del Dólar y Escenarios', '美元影响与假设估值', 'ドル影響とシナリオ試算', 'डॉलर प्रभाव और अनुमानित मूल्य'],
    "How US Dollar shifts, past highs, or future forecasts would change your stack's value": ['ดูว่าการเปลี่ยนของดอลลาร์ จุดสูงสุดเก่า หรือคาดการณ์อนาคตจะเปลี่ยนมูลค่าคลังคุณเท่าไร', 'ເບິ່ງວ່າການປ່ຽນຂອງໂດລາ ຈຸດສູງສຸດເກົ່າ ຫຼື ຄາດຄະເນອະນາຄົດຈະປ່ຽນມູນຄ່າຄັງເຈົ້າເທົ່າໃດ', 'Cómo cambiaría el valor de tu reserva ante movimientos del dólar, máximos o pronósticos', '展示美元变动、历史高点及未来预测对持仓总值的影响', '米ドル変動・過去高値・将来予測による評価額変化を表示', 'डॉलर के उतार-चढ़ाव, पुराने उच्चतम या भविष्य के अनुमान आपके भंडार को कैसे बदलेंगे'],
    'Add holdings above to see what-if values for your stack.': ['เพิ่มข้อมูลทอง/เงินด้านบนเพื่อดูมูลค่าจำลอง', 'ເພີ່ມຂໍ້ມູນຄຳ/ເງິນດ້ານເທິງເພື່ອເບິ່ງມູນຄ່າຈຳລອງ', 'Añade tus metales arriba para ver escenarios de valor.', '在上方添加持仓即可查看情景估值。', '上で保有量を追加するとシナリオ評価が表示されます。', 'अनुमानित मूल्य देखने के लिए ऊपर होल्डिंग्स जोड़ें।'],

