    'Daily 8:00 AM Morning Brief (Phone Push)': ['สรุปข่าวเช้า 8:00 น. ทุกวัน (แจ้งเตือนมือถือ)', 'ສະຫຼຸບຂ່າວເຊົ້າ 8:00 ທຸກມື້ (ແຈ້ງເຕືອນມືຖື)', 'Resumen Matutino Diario 8:00 AM', '每日早8点市场简报（手机推送）', '毎朝8時モーニング速報（スマホ通知）', 'दैनिक सुबह 8:00 बजे मॉर्निंग ब्रीफ (फ़ोन पुश)'],
    'Quiet Hours (Do Not Disturb)': ['ช่วงเวลางดรบกวน (เวลานอน)', 'ຊ່ວງເວລາງົດລົບກວນ (ເວລານອນ)', 'Horas de Silencio (No Molestar)', '夜间免打扰时段', 'おやすみ時間帯（サイレント）', 'शांत घंटे (परेशान न करें)'],
    'Quiet Start (ET)': ['เริ่มงดรบกวน (ET)', 'ເລີ່ມງົດລົບກວນ (ET)', 'Inicio Silencio (ET)', '免打扰开始 (ET)', '開始時刻 (ET)', 'शांत शुरुआत (ET)'],
