          zh: `支撑 ${m[1].trim()} · 阻力 ${m[2].trim()}`,
          ja: `支持線 ${m[1].trim()}・抵抗線 ${m[2].trim()}`,
          hi: `सपोर्ट ${m[1].trim()} · रेज़िस्टेंस ${m[2].trim()}`,
