    'Auto-healed to Gold-API Spot after primary feed timed out or failed sanity bounds.': ['สลับไปใช้แหล่งราคาสำรองอัตโนมัติหลังแหล่งหลักหมดเวลาหรือข้อมูลผิดปกติ', 'ສະຫຼັບໄປໃຊ້ແຫຼ່ງລາຄາສຳຮອງອັດຕະໂນມັດຫຼັງແຫຼ່ງຫຼັກໝົດເວລາ', 'Cambio automático a fuente de respaldo tras tiempo de espera agotado.', '主数据源超时或超出合理范围，已自动切换至备用实时报价源。', 'メインソースのタイムアウト後にバックアップ価格へ自動切替しました。', 'मुख्य फ़ीड के टाइमआउट के बाद स्वतः बैकअप लाइव फ़ीड पर स्विच हो गया।'],

    // Outlook: Forecast, Verdicts, Weather, What-If Chips, Drivers, Vaults & Miners, Sim
    'Good Dip-Buy Zone': ['โซนน่าทยอยซื้อตอนย่อ', 'ເຂດໜ້າທະຍອຍຊື້ຕອນລາຄາລົງ', 'Buena Zona de Compra en Caída', '优质逢低买入区', '押し目買い好機', 'अच्छा डिप-खरीद क्षेत्र'],
    'Prices have pulled back enough that buyers often step in here. Good area to slowly add near the floor price.': ['ราคาย่อลงมามากพอที่แรงซื้อมักเริ่มกลับเข้ามา เป็นโซนที่ดีในการค่อยๆ ทยอยสะสมใกล้แนวรับ', 'ລາຄາລົງມາພໍສົມຄວນທີ່ແຮງຊື້ມັກເຂົ້າມາ ເປັນເຂດທີ່ດີໃນການຄ່ອຍໆຊື້ສະສົມໃກ້ແນວຮັບ', 'Los precios han bajado a un nivel donde suelen entrar compradores. Buena zona para acumular gradualmente.', '价格已回调至买盘常介入的位置，适合在支撑位附近分批逢低布局。', '買いが入りやすい水準まで下落しています。支持線付近で少しずつ買い増す好機です。', 'कीमतें इतनी नीचे आ गई हैं कि यहाँ खरीदार अक्सर लौटते हैं। सपोर्ट के पास धीरे-धीरे जोड़ने का अच्छा क्षेत्र।'],
    'Squeeze Active — Wait for Dips': ['มีแรงบีบขึ้นแรง — รอย่อค่อยซื้อ', 'ມີແຮງດັນຂຶ້ນແຮງ — ລໍລາຄາລົງຄ່ອຍຊື້', 'Presión Alcista Activa — Espera Caídas', '逼空行情活跃 — 耐心等回调', '急騰圧力あり — 押し目待ち推奨', 'तेज़ दबाव सक्रिय — गिरावट का इंतज़ार करें'],
    'Heavy short-squeeze pressure can cause sharp jumps, but avoid chasing big spikes — look for pullbacks toward the floor price.': ['แรงบีบฝั่งขายอาจทำให้ราคาพุ่งแรงกะทันหัน แต่หลีกเลี่ยงการไล่ราคาสูง รอย่อลงมาใกล้แนวรับจะปลอดภัยกว่า', 'ແຮງດັນອາດເຮັດໃຫ້ລາຄາພຸ່ງແຮງ ແຕ່ຄວນຫຼີກລ່ຽງການໄລ່ຊື້ສູງ ໃຫ້ລໍຈັງຫວະລາຄາລົງໃກ້ແນວຮັບ', 'La presión puede causar saltos bruscos; evita perseguir picos y busca retrocesos hacia el soporte.', '逼空压力可能引发急涨，但切忌追高，等待回踩支撑位附近更稳妥。', '急騰が起きやすい状況ですが高値追いは避け、支持線への押し目を狙うのが安全です。', 'भारी दबाव से तेज़ उछाल आ सकते हैं, लेकिन ऊँची कीमत पर न भागें — सपोर्ट की ओर गिरावट देखें।'],
    'Big Swings Ahead': ['ระวังราคาเหวี่ยงแรงเร็วๆ นี้', 'ລະວັງລາຄາຜັນຜວນແຮງໄວໆນີ້', 'Fuertes Oscilaciones Próximas', '前方预计剧烈波动', '大きな値動きに警戒', 'आगे बड़े उतार-चढ़ाव'],
    'Bumpy days ahead! Expect sudden jumps or drops — stay patient and avoid chasing.': ['ช่วงนี้ตลาดอาจเหวี่ยงแรง เตรียมรับมือการขึ้นลงฉับพลัน ใจเย็นๆ และอย่าไล่ราคา', 'ຊ່ວງນີ້ຕະຫຼາດອາດຜັນຜວນແຮງ ກຽມຮັບມືການຂຶ້ນລົງໄວ ໃຈເຢັນໆ ແລະ ຢ່າໄລ່ລາຄາ', 'Se esperan días agitados con saltos y caídas repentinas — ten paciencia y no persigas el precio.', '未来数日波动加大！请防范急涨急跌，保持耐心切勿追涨杀跌。', '荒い値動きが予想されます！急騰・急落に備え、焦って追いかけないでください。', 'आगे उथल-पुथल भरे दिन! अचानक उछाल या गिरावट की उम्मीद करें — धैर्य रखें।'],
    'Calm Skies': ['ตลาดค่อนข้างสงบ', 'ຕະຫຼາດຂ້ອນຂ້າງສະຫງົບ', 'Cielo Despejado', '行情平稳', '落ち着いた相場', 'शांत बाज़ार'],
    'Normal Swings': ['ความผันผวนปกติ', 'ຄວາມຜັນຜວນປົກກະຕິ', 'Oscilaciones Normales', '常规波动', '通常の値動き', 'सामान्य उतार-चढ़ाव'],
    'High Inflation': ['เงินเฟ้อพุ่งสูง', 'ເງິນເຟີ້ພຸ່ງສູງ', 'Inflación Alta', '高通胀升温', '高インフレ', 'उच्च महंगाई'],
