    'Drag either slider to see how Gold & Silver usually react in the first hour versus one week after an inflation or interest-rate surprise.': ['เลื่อนแถบใดก็ได้เพื่อดูว่าทองคำและเงินมักตอบสนองอย่างไรในชั่วโมงแรกเทียบกับ 1 สัปดาห์หลังข่าวเงินเฟ้อหรือดอกเบี้ย', 'ເລື່ອນແຖບໃດກໍໄດ້ເພື່ອເບິ່ງປະຕິກິລິຍາຄຳ ແລະ ເງິນໃນ 1 ຊມ. ທຽບກັບ 1 ອາທິດ', 'Mueve cualquier control para ver cómo reaccionan el oro y la plata en la primera hora frente a una semana.', '拖动任一滑块，查看通胀或利率意外公布后1小时与1周内金银的常见反应。', 'スライダーを動かすと、インフレや金利発表の1時間後と1週間後の反応を比較できます。', 'महंगाई या ब्याज दर के झटके के 1 घंटे बनाम 1 सप्ताह बाद सोना-चांदी की प्रतिक्रिया देखने के लिए स्लाइडर खींचें।'],
