    'Big Traders & Mining Stocks': ['รายใหญ่และหุ้นเหมืองทอง', 'ລາຍໃຫຍ່ ແລະ ຫຸ້ນບໍ່ແຮ່ຄຳ', 'Grandes Operadores y Mineras', '大机构持仓与矿业股', '大口投機筋・鉱山株', 'बड़े ट्रेडर्स और खदान शेयर'],
    'Paper Contracts vs. Vaults': ['สัญญากระดาษเทียบคลังทอง', 'ສັນຍາເຈ້ຍທຽບຄັງຄຳ', 'Contratos de Papel vs. Bóvedas', '纸合约对比金库库存', 'ペーパー契約 vs 保管庫', 'कागज़ी अनुबंध बनाम तिजोरियाँ'],
    'COVID Liquidity Crash → Fed Cuts (Mar 2020)': ['วิกฤตโควิด → เฟดลดดอกเบี้ยฉุกเฉิน (มี.ค. 2020)', 'ວິກິດໂຄວິດ → ເຟດຫຼຸດດອກເບ້ຍສຸກເສີນ (2020)', 'Caída COVID → Recortes de la Fed (Mar 2020)', '疫情流动性冲击 → 美联储紧急降息（2020年3月）', 'コロナ危機→FRB緊急利下げ（2020年3月）', 'कोविड संकट → फेड दर कटौती (मार्च 2020)'],
    'Acute stock margin calls caused a brief dip in silver first, followed by a massive rally after emergency cuts.': ['แรงขายล้างพอร์ตหุ้นกดเงินร่วงสั้นๆ ก่อนพุ่งแรงมากหลังเฟดลดดอกเบี้ยฉุกเฉิน', 'ແຮງຂາຍຫຸ້ນກົດເງິນລົງສັ້ນໆ ກ່ອນພຸ່ງແຮງຫຼັງເຟດຫຼຸດດອກເບ້ຍສຸກເສີນ', 'Las llamadas de margen hundieron brevemente la plata antes de un enorme repunte tras los recortes.', '股市急跌引发流动性抛售令白银短暂下挫，随后在紧急降息刺激下迎来暴涨。', '株安に伴う現金化で銀が一時下落した後、緊急利下げで大規模な上昇に転じました。', 'शेयर मार्जिन कॉल से चांदी थोड़ी गिरी, फिर आपातकालीन दर कटौती के बाद बड़ी तेज़ी आई।'],
    'Record Central Bank Buying & Fed Pivot (2024)': ['ธนาคารกลางซื้อทองทำสถิติและเฟดกลับทิศดอกเบี้ย (2024)', 'ທະນາຄານກາງຊື້ຄຳສະຖິຕິ ແລະ ເຟດປ່ຽນທິດດອກເບ້ຍ (2024)', 'Compras Récord de Bancos Centrales y Giro Fed (2024)', '央行创纪录购金与美联储转向降息（2024年）', '中銀の記録的金購入とFRB利下げ転換（2024年）', 'केंद्रीय बैंकों की रिकॉर्ड खरीदारी और फेड बदलाव (2024)'],
    'Sovereign gold accumulation paired with rate-cut pricing fueled sustained upward momentum.': ['การสะสมทองของธนาคารกลางควบคู่การคาดการณ์ลดดอกเบี้ยช่วยดันราคาขึ้นต่อเนื่อง', 'ການສະສົມຄຳຂອງທະນາຄານກາງຄູ່ກັບການຄາດຫຼຸດດອກເບ້ຍຊ່ວຍດັນລາຄາຂຶ້ນຕໍ່ເນື່ອງ', 'La acumulación soberana de oro junto a expectativas de recortes impulsó una subida sostenida.', '多国央行持续囤金叠加强烈降息预期，推动金银持续走高。', '各国の金買い増しと利下げ織り込みが持続的な上昇モメンタムを生みました。', 'केंद्रीय बैंकों द्वारा सोना जमा करने और दर कटौती की उम्मीद ने लगातार तेज़ी दी।'],
    'Russia–Ukraine Invasion (Feb 2022)': ['ความขัดแย้งรัสเซีย–ยูเครน (ก.พ. 2022)', 'ຄວາມຂັດແຍ້ງຣັດເຊຍ–ຢູເຄຣນ (2022)', 'Invasión Rusia–Ucrania (Feb 2022)', '俄乌冲突爆发（2022年2月）', 'ロシア・ウクライナ侵攻（2022年2月）', 'रूस–यूक्रेन संघर्ष (फ़रवरी 2022)'],
    'Acute geopolitical shock plus commodity inflation triggered an immediate safe-haven spike.': ['วิกฤตภูมิรัฐศาสตร์ฉับพลันร่วมกับเงินเฟ้อสินค้าโภคภัณฑ์จุดชนวนแรงซื้อสินทรัพย์ปลอดภัยทันที', 'ວິກິດສົງຄາມກະທັນຫັນ ແລະ ເງິນເຟີ້ເຮັດໃຫ້ມີແຮງຊື້ຄຳຫຼົບໄພທັນທີ', 'El choque geopolítico y la inflación de materias primas desataron una subida inmediata de refugio.', '突发地缘冲击叠加商品通胀，迅速触发强烈的避险飙升行情。', '急激な地政学ショックと資源インフレにより即座に安全資産買いが急増しました。', 'अचानक भू-राजनीतिक संकट और महंगाई ने सुरक्षित निवेश के रूप में तुरंत उछाल लाया।'],

    // Vaults & Miners + Odds & News
    'Moving Together': ['เคลื่อนไหวไปพร้อมกัน', 'ເຄື່ອນໄຫວໄປພ້ອມກັນ', 'Moviéndose Juntos', '走势同步', '同調して推移', 'साथ-साथ चल रहे हैं'],
