    'Mining stocks are moving right in line with physical Gold & Silver right now — no unusual early warning.': ['หุ้นเหมืองกำลังเคลื่อนไหวสอดคล้องกับราคาทองและเงินจริงในตอนนี้ — ยังไม่มีสัญญาณเตือนล่วงหน้าผิดปกติ', 'ຫຸ້ນບໍ່ແຮ່ກຳລັງເຄື່ອນໄຫວສອດຄ່ອງກັບຄຳ ແລະ ເງິນຈິງຕອນນີ້ — ຍັງບໍ່ມີສັນຍານຜິດປົກກະຕິ', 'Las mineras se mueven en línea con el oro y la plata ahora — sin señal temprana inusual.', '矿业股当前与黄金白银现货同步波动 — 暂无异常领先预警信号。', '鉱山株は現在、金・銀現物と歩調を合わせて動いており異常な先行シグナルはありません。', 'खदान शेयर अभी भौतिक सोना-चांदी के साथ ही चल रहे हैं — कोई असामान्य शुरुआती चेतावनी नहीं।'],
    'Monthly Gold & Silver Contract Expiry': ['วันหมดอายุสัญญาฟิวเจอร์สรายเดือน', 'ວັນໝົດອາຍຸສັນຍາລ່ວງໜ້າລາຍເດືອນ', 'Vencimiento Mensual de Contratos', '月度黄金白银期货合约到期', '月次 金・銀先物限月満期', 'मासिक सोना-चांदी कॉन्ट्रैक्ट समाप्ति'],
    'Big contract expirations often cause sudden same-day price swings': ['วันหมดอายุสัญญาใหญ่มักทำให้ราคาเหวี่ยงแรงภายในวันเดียวกัน', 'ວັນໝົດອາຍຸສັນຍາໃຫຍ່ມັກເຮັດໃຫ້ລາຄາຜັນຜວນແຮງໃນມື້ດຽວກັນ', 'Los grandes vencimientos suelen provocar movimientos bruscos ese mismo día', '大合约到期日往往会引发当日价格剧烈波动', '大きな限月満期日は当日中の急変動を引き起こしやすいです', 'बड़ी कॉन्ट्रैक्ट समाप्ति पर उसी दिन अचानक तेज़ उतार-चढ़ाव हो सकते हैं'],
    'Dec Gold & Silver Vault Delivery Start': ['เริ่มวันส่งมอบทองและเงินจริงเดือน ธ.ค.', 'ເລີ່ມວັນສົ່ງມອບຄຳ ແລະ ເງິນຈິງເດືອນ ທ.ວ.', 'Inicio de Entrega Física Dic.', '12月黄金白银金库交割开始', '12月限 金・銀実物受渡開始', 'दिसंबर सोना-चांदी तिजोरी डिलीवरी शुरू'],
