    'No personal calls logged yet. Pick Gold or Silver above and tap "Call UP" or "Call DOWN" to race against Bullion Pulse\'s model!': ['ยังไม่มีประวัติการทายของคุณ เลือกทองคำหรือเงินด้านบนแล้วแตะ "ทายขึ้น" หรือ "ทายลง" เพื่อแข่งความแม่นยำกับระบบ!', 'ຍັງບໍ່ມີປະຫວັດການທາຍ ເລືອກຄຳ ຫຼື ເງິນດ້ານເທິງແລ້ວແຕະ "ທາຍຂຶ້ນ" ຫຼື "ທາຍລົງ"!', 'Aún no hay predicciones. Elige Oro o Plata arriba y toca "Sube" o "Baja" para competir con el modelo.', '暂无个人预测记录。请在上方选择黄金或白银并点击“看涨”或“看跌”与模型一较高下！', 'まだ個人予想がありません。上で金または銀を選び「上昇予想」か「下落予想」をタップして対決しましょう！', 'अभी कोई व्यक्तिगत अनुमान नहीं है। ऊपर सोना या चांदी चुनें और "ऊपर" या "नीचे" टैप करें!'],

