    'Showing your private stack vs. S&P 500 (blue dashed) and inflation-eroded cash (red dashed). Toggle "My Buys" on the main chart to plot each purchase lot directly on the candlesticks.': ['เปรียบเทียบคลังส่วนตัวของคุณกับหุ้น S&P 500 (เส้นประฟ้า) และเงินสดหลังหักเงินเฟ้อ (เส้นประแดง) เปิด "จุดที่ฉันซื้อ" บนกราฟหลักเพื่อดูทุกจุดที่คุณซื้อ', 'ປຽບທຽບຄັງສ່ວນຕົວຂອງເຈົ້າກັບຫຸ້ນ S&P 500 (ເສັ້ນປະສີຟ້າ) ແລະ ເງິນສົດ (ເສັ້ນປະສີແດງ)', 'Muestra tu reserva frente al S&P 500 (azul) y efectivo con inflación (rojo). Activa "Mis Compras" en el gráfico principal para marcar cada compra.', '展示你的私密持仓对比标普500（蓝色虚线）及受通胀侵蚀的现金（红色虚线）。在主图开启“我的买点”可标出每笔购入。', '保有資産をS&P 500（青破線）とインフレ調整後現金（赤破線）と比較中。メインチャートで「自分の買値」をオンにすると購入点が表示されます。', 'आपका निजी भंडार बनाम S&P 500 (नीली रेखा) और महंगाई से घटी नकदी (लाल रेखा)। मुख्य चार्ट पर "मेरी खरीद" चालू करें।'],
